// hadiths.js — 365 Daily Hadiths for MSA Ukkuda Islamic Content Hub
// One Hadith per day, full year cycle. All from authenticated collections.
window.HADITHS_365 = [
  { arabic: 'إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ', text: '"Actions are judged by intentions, and every person shall have what they intended."', source: 'Sahih Al-Bukhari 1 · Sahih Muslim 1907', day: 'On Intentions' },
  { arabic: 'الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ', text: '"A Muslim is one from whose tongue and hand the Muslims are safe."', source: 'Sahih Al-Bukhari 10', day: 'On Character' },
  { arabic: 'لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ', text: '"None of you truly believes until he loves for his brother what he loves for himself."', source: 'Sahih Al-Bukhari 13 · Sahih Muslim 45', day: 'On Brotherhood' },
  { arabic: 'طَلَبُ الْعِلْمِ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ', text: '"Seeking knowledge is an obligation upon every Muslim."', source: 'Ibn Majah 224', day: 'On Knowledge' },
  { arabic: 'خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ', text: '"The best of you are those who learn the Quran and teach it."', source: 'Sahih Al-Bukhari 5027', day: 'On the Quran' },
  { arabic: 'الدِّينُ النَّصِيحَةُ', text: '"Religion is sincere advice."', source: 'Sahih Muslim 55', day: 'On Sincerity' },
  { arabic: 'مَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ', text: '"Whoever believes in Allah and the Last Day, let him speak good or remain silent."', source: 'Sahih Al-Bukhari 6018', day: 'On Speech' },
  { arabic: 'أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا', text: '"The most complete of the believers in faith are those with the best character."', source: 'Abu Dawud 4682', day: 'On Good Character' },
  { arabic: 'الصِّيَامُ جُنَّةٌ', text: '"Fasting is a shield against sins."', source: 'Sahih Al-Bukhari 1894', day: 'On Fasting' },
  { arabic: 'مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ', text: '"Whoever fasts Ramadan out of faith and seeking reward, his past sins will be forgiven."', source: 'Sahih Al-Bukhari 38', day: 'On Ramadan' },
  { arabic: 'مَنْ تَوَاضَعَ لِلَّهِ رَفَعَهُ اللَّهُ', text: '"Whoever humbles himself for Allah, Allah will raise him."', source: 'Sahih Muslim 2588', day: 'On Humility' },
  { arabic: 'الْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ', text: '"A kind word is charity."', source: 'Sahih Al-Bukhari 2989', day: 'On Kindness' },
  { arabic: 'إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ', text: '"Indeed Allah is gentle and He loves gentleness in all matters."', source: 'Sahih Al-Bukhari 6927', day: 'On Gentleness' },
  { arabic: 'اتَّقِ اللهَ حَيْثُمَا كُنْتَ وَأَتْبِعِ السَّيِّئَةَ الْحَسَنَةَ تَمْحُهَا', text: '"Fear Allah wherever you are, and follow a bad deed with a good one to erase it."', source: 'Tirmidhi 1987', day: 'On Taqwa' },
  { arabic: 'مَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ طَرِيقًا إِلَى الْجَنَّةِ', text: '"Whoever travels a path seeking knowledge, Allah eases for him a path to Paradise."', source: 'Sahih Muslim 2699', day: 'On Seeking Knowledge' },
  { arabic: 'الصَّلَوَاتُ الْخَمْسُ وَالْجُمُعَةُ إِلَى الْجُمُعَةِ كَفَّارَةٌ لِمَا بَيْنَهُنَّ', text: '"The five daily prayers and one Jumu\'ah to the next are expiations for what is between them."', source: 'Sahih Muslim 233', day: 'On Prayer' },
  { arabic: 'إِنَّ اللَّهَ لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ', text: '"Allah does not look at your appearance or wealth, but at your hearts and deeds."', source: 'Sahih Muslim 2564', day: 'On the Heart' },
  { arabic: 'مَنْ أَحَبَّ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ فَلْيَصِلْ رَحِمَهُ', text: '"Whoever wishes provision to be expanded, let him maintain ties of kinship."', source: 'Sahih Al-Bukhari 5986', day: 'On Family Ties' },
  { arabic: 'خَيْرُ النَّاسِ أَنْفَعُهُمْ لِلنَّاسِ', text: '"The best of people are those most beneficial to others."', source: 'Al-Mu\'jam Al-Awsat — Sahih', day: 'On Service' },
  { arabic: 'إِنَّ مِنْ أَحَبِّكُمْ إِلَيَّ أَحْسَنَكُمْ أَخْلَاقًا', text: '"The most beloved among you to me are those with the best character."', source: 'Sahih Al-Bukhari 3759', day: 'On Noble Character' },
  { arabic: 'بُنِيَ الإِسْلَامُ عَلَى خَمْسٍ', text: '"Islam is built upon five pillars: the testimony, prayer, zakat, fasting Ramadan, and Hajj."', source: 'Sahih Al-Bukhari 8', day: 'On Pillars of Islam' },
  { arabic: 'الإِيمَانُ بِضْعٌ وَسِتُّونَ شُعْبَةً', text: '"Faith has over sixty branches, the highest is saying La ilaha illallah and the lowest is removing harm from the road."', source: 'Sahih Al-Bukhari 9', day: 'On Faith' },
  { arabic: 'مَنْ غَشَّنَا فَلَيْسَ مِنَّا', text: '"Whoever cheats us is not one of us."', source: 'Sahih Muslim 101', day: 'On Honesty' },
  { arabic: 'الْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضًا', text: '"A believer to another believer is like a building — each part strengthens the other."', source: 'Sahih Al-Bukhari 481', day: 'On Unity' },
  { arabic: 'لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ', text: '"The strong is not the one who wrestles others down; the strong is the one who controls himself in anger."', source: 'Sahih Al-Bukhari 6114', day: 'On Controlling Anger' },
  { arabic: 'إِيَّاكُمْ وَالظَّنَّ فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ', text: '"Beware of suspicion, for suspicion is the most false of speech."', source: 'Sahih Al-Bukhari 5144', day: 'On Good Opinion' },
  { arabic: 'لَا تَحَاسَدُوا وَلَا تَبَاغَضُوا وَكُونُوا عِبَادَ اللهِ إِخْوَانًا', text: '"Do not envy one another, do not hate one another — be servants of Allah and brothers."', source: 'Sahih Muslim 2563', day: 'On Brotherhood' },
  { arabic: 'مَنْ كَظَمَ غَيْظًا وَهُوَ قَادِرٌ عَلَى أَنْ يُنْفِذَهُ دَعَاهُ اللَّهُ عَلَى رُءُوسِ الْخَلَائِقِ', text: '"Whoever suppresses his anger while able to act upon it, Allah will call him before all of creation."', source: 'Abu Dawud 4777', day: 'On Patience with Anger' },
  { arabic: 'صِلْ مَنْ قَطَعَكَ وَأَعْطِ مَنْ حَرَمَكَ وَاعْفُ عَمَّنْ ظَلَمَكَ', text: '"Maintain ties with whoever cuts you off, give to whoever withholds from you, and forgive whoever wrongs you."', source: 'Ahmad 17452 — Sahih', day: 'On Forgiveness' },
  { arabic: 'مَنْ لَا يَرْحَمُ النَّاسَ لَا يَرْحَمُهُ اللَّهُ', text: '"Whoever does not show mercy to people, Allah will not show mercy to him."', source: 'Sahih Al-Bukhari 7376', day: 'On Mercy' },
  { arabic: 'الرَّاحِمُونَ يَرْحَمُهُمُ الرَّحْمَنُ', text: '"The merciful will be shown mercy by the Most Merciful."', source: 'Abu Dawud 4941', day: 'On Mercy' },
  { arabic: 'إِنَّ اللَّهَ جَمِيلٌ يُحِبُّ الْجَمَالَ', text: '"Indeed Allah is beautiful and He loves beauty."', source: 'Sahih Muslim 91', day: 'On Excellence' },
  { arabic: 'إِنَّ اللَّهَ كَتَبَ الإِحْسَانَ عَلَى كُلِّ شَيْءٍ', text: '"Allah has prescribed Ihsan (excellence) in all things."', source: 'Sahih Muslim 1955', day: 'On Ihsan' },
  { arabic: 'لَا ضَرَرَ وَلَا ضِرَارَ', text: '"There should be neither harming nor reciprocating harm."', source: 'Ibn Majah 2340 — Sahih', day: 'On Justice' },
  { arabic: 'مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ', text: '"Whoever sees an evil, let him change it with his hand; if he cannot, then with his tongue; if he cannot, then with his heart."', source: 'Sahih Muslim 49', day: 'On Forbidding Evil' },
  { arabic: 'أَدِّ الْأَمَانَةَ إِلَى مَنِ ائْتَمَنَكَ وَلَا تَخُنْ مَنْ خَانَكَ', text: '"Return the trust to whoever entrusted you, and do not betray whoever betrayed you."', source: 'Abu Dawud 3534', day: 'On Trust' },
  { arabic: 'أَحَبُّ الأَعْمَالِ إِلَى اللهِ أَدْوَمُهَا وَإِنْ قَلَّ', text: '"The most beloved deeds to Allah are those done consistently, even if small."', source: 'Sahih Al-Bukhari 6465', day: 'On Consistency' },
  { arabic: 'إِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ', text: '"Truthfulness leads to righteousness and righteousness leads to Paradise."', source: 'Sahih Al-Bukhari 6094', day: 'On Truthfulness' },
  { arabic: 'لَا تَغْضَبْ', text: '"Do not get angry." (Said three times when asked for advice.)', source: 'Sahih Al-Bukhari 6116', day: 'On Anger' },
  { arabic: 'الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يُسْلِمُهُ', text: '"A Muslim is the brother of a Muslim — he does not wrong him nor does he let him down."', source: 'Sahih Al-Bukhari 2442', day: 'On Brotherhood' },
  { arabic: 'حَسْبُ امْرِئٍ مِنَ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ', text: '"It is enough evil for a person to belittle his Muslim brother."', source: 'Sahih Muslim 2564', day: 'On Respecting Others' },
  { arabic: 'مَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالْآخِرَةِ', text: '"Whoever conceals a Muslim\'s faults, Allah will conceal his faults in this world and the next."', source: 'Sahih Muslim 2699', day: 'On Concealing Faults' },
  { arabic: 'مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً', text: '"Whoever relieves a believer\'s distress, Allah will relieve his distress on the Day of Resurrection."', source: 'Sahih Muslim 2699', day: 'On Helping Others' },
  { arabic: 'وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ', text: '"Allah is in the aid of the servant as long as the servant is in the aid of his brother."', source: 'Sahih Muslim 2699', day: 'On Helping Others' },
  { arabic: 'الصَّبْرُ ضِيَاءٌ', text: '"Patience is a light."', source: 'Sahih Muslim 223', day: 'On Patience' },
  { arabic: 'وَالصَّدَقَةُ بُرْهَانٌ', text: '"And charity is a proof of faith."', source: 'Sahih Muslim 223', day: 'On Charity' },
  { arabic: 'مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ', text: '"Charity does not decrease wealth."', source: 'Sahih Muslim 2588', day: 'On Giving' },
  { arabic: 'أَفْضَلُ الصَّدَقَةِ أَنْ تَصَدَّقَ وَأَنْتَ صَحِيحٌ', text: '"The best charity is that given when you are healthy and prosperous."', source: 'Sahih Al-Bukhari 1419', day: 'On Charity' },
  { arabic: 'كُلُّ مَعْرُوفٍ صَدَقَةٌ', text: '"Every act of kindness is charity."', source: 'Sahih Al-Bukhari 6021', day: 'On Kindness' },
  { arabic: 'تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ صَدَقَةٌ', text: '"Smiling in the face of your brother is charity."', source: 'Tirmidhi 1956 — Sahih', day: 'On a Smile' },
  { arabic: 'إِمَاطَةُ الْأَذَى عَنِ الطَّرِيقِ صَدَقَةٌ', text: '"Removing harm from the road is charity."', source: 'Sahih Al-Bukhari 2989', day: 'On Small Good Deeds' },
  { arabic: 'احْرِصْ عَلَى مَا يَنْفَعُكَ وَاسْتَعِنْ بِاللَّهِ وَلَا تَعْجَزْ', text: '"Be keen on what benefits you, seek help from Allah, and do not be lazy."', source: 'Sahih Muslim 2664', day: 'On Striving' },
  { arabic: 'وَاعْلَمْ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ', text: '"Know that what has befallen you was never going to miss you."', source: 'Sahih Muslim 2664', day: 'On Qadar' },
  { arabic: 'مَنْ صَلَّى عَلَيَّ صَلَاةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا', text: '"Whoever sends one blessing upon me, Allah sends ten blessings upon him."', source: 'Sahih Muslim 408', day: 'On Salah upon the Prophet ﷺ' },
  { arabic: 'الدُّعَاءُ هُوَ الْعِبَادَةُ', text: '"Supplication is worship."', source: 'Abu Dawud 1479', day: 'On Dua' },
  { arabic: 'يَسِّرُوا وَلَا تُعَسِّرُوا وَبَشِّرُوا وَلَا تُنَفِّرُوا', text: '"Make things easy and do not make them difficult. Give glad tidings and do not cause aversion."', source: 'Sahih Al-Bukhari 69', day: 'On Ease in Religion' },
  { arabic: 'أَحَبُّ الْبِلَادِ إِلَى اللهِ مَسَاجِدُهَا', text: '"The most beloved places to Allah are the mosques."', source: 'Sahih Muslim 671', day: 'On the Masjid' },
  { arabic: 'مَنْ بَنَى مَسْجِدًا لِلَّهِ بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ', text: '"Whoever builds a mosque for Allah, Allah will build for him a house in Paradise."', source: 'Sahih Al-Bukhari 450', day: 'On Building Masajid' },
  { arabic: 'الْجَنَّةُ تَحْتَ أَقْدَامِ الْأُمَّهَاتِ', text: '"Paradise lies at the feet of mothers."', source: 'Ibn Majah 2781 — Sahih', day: 'On Mothers' },
  { arabic: 'رِضَا اللهِ فِي رِضَا الْوَالِدِ وَسَخَطُ اللهِ فِي سَخَطِ الْوَالِدِ', text: '"The pleasure of Allah is in the pleasure of the parent, and the anger of Allah is in the anger of the parent."', source: 'Tirmidhi 1899 — Sahih', day: 'On Parents' },
  { arabic: 'إِذَا مَاتَ الإِنْسَانُ انْقَطَعَ عَمَلُهُ إِلَّا مِنْ ثَلَاثٍ', text: '"When a person dies, his deeds stop except for three: a continuous charity, knowledge benefited from, or a righteous child who prays for him."', source: 'Sahih Muslim 1631', day: 'On Legacy' },
  { arabic: 'نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ الصِّحَّةُ وَالْفَرَاغُ', text: '"Two blessings that many people are cheated of: health and free time."', source: 'Sahih Al-Bukhari 6412', day: 'On Health and Time' },
  { arabic: 'كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ', text: '"Be in this world as if you were a stranger or a traveler."', source: 'Sahih Al-Bukhari 6416', day: 'On the Dunya' },
  { arabic: 'ازْهَدْ فِي الدُّنْيَا يُحِبَّكَ اللَّهُ', text: '"Be indifferent to this world and Allah will love you."', source: 'Ibn Majah 4102 — Sahih', day: 'On Zuhd' },
  { arabic: 'لَيْسَ الْغِنَى عَنْ كَثْرَةِ الْعَرَضِ وَلَكِنَّ الْغِنَى غِنَى النَّفْسِ', text: '"Richness is not having many possessions, but richness is the richness of the soul."', source: 'Sahih Al-Bukhari 6446', day: 'On Contentment' },
  { arabic: 'أَعْظَمُ الذُّنُوبِ عِنْدَ اللهِ أَنْ تَتَّخِذَ لِلَّهِ نِدًّا وَهُوَ خَلَقَكَ', text: '"The greatest sin before Allah is that you set up a rival to Him while He created you."', source: 'Sahih Al-Bukhari 6001', day: 'On Tawhid' },
  { arabic: 'مَنْ قَالَ لَا إِلَهَ إِلَّا اللهُ خَالِصًا مِنْ قَلْبِهِ دَخَلَ الْجَنَّةَ', text: '"Whoever says La ilaha illallah sincerely from his heart will enter Paradise."', source: 'Sahih Al-Bukhari 128', day: 'On Tawhid' },
  { arabic: 'سُبْحَانَ اللهِ وَبِحَمْدِهِ سُبْحَانَ اللهِ الْعَظِيمِ', text: '"SubhanAllah wa bihamdihi, SubhanAllah al-Adhim — Two words light on the tongue, heavy on the scale, beloved to the Most Merciful."', source: 'Sahih Al-Bukhari 6682', day: 'On Dhikr' },
  { arabic: 'مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لَا يَذْكُرُهُ مَثَلُ الْحَيِّ وَالْمَيِّتِ', text: '"The example of one who remembers his Lord compared to one who does not is like the living compared to the dead."', source: 'Sahih Al-Bukhari 6407', day: 'On Dhikr' },
  { arabic: 'كُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْؤُولٌ عَنْ رَعِيَّتِهِ', text: '"Every one of you is a shepherd and every one of you is responsible for his flock."', source: 'Sahih Al-Bukhari 893', day: 'On Responsibility' },
  { arabic: 'أَفْضَلُ الْأَعْمَالِ الصَّلَاةُ عَلَى وَقْتِهَا', text: '"The best of deeds is prayer performed at its proper time."', source: 'Sahih Al-Bukhari 527', day: 'On Prayer' },
  { arabic: 'مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ خَرَجَتْ خَطَايَاهُ', text: '"Whoever performs wudu perfectly, his sins come out from his body, even from under his nails."', source: 'Sahih Muslim 245', day: 'On Purification' },
  { arabic: 'الطُّهُورُ شَطْرُ الإِيمَانِ', text: '"Purification is half of faith."', source: 'Sahih Muslim 223', day: 'On Cleanliness' },
  { arabic: 'إِنَّ اللَّهَ طَيِّبٌ لَا يَقْبَلُ إِلَّا طَيِّبًا', text: '"Indeed Allah is pure and He accepts only what is pure."', source: 'Sahih Muslim 1015', day: 'On Halal Sustenance' },
  { arabic: 'الْحَلَالُ بَيِّنٌ وَالْحَرَامُ بَيِّنٌ وَبَيْنَهُمَا أُمُورٌ مُشْتَبِهَاتٌ', text: '"The halal is clear and the haram is clear, and between them are doubtful matters — whoever avoids the doubtful has protected his religion."', source: 'Sahih Al-Bukhari 52', day: 'On Halal and Haram' },
  { arabic: 'دَعْ مَا يَرِيبُكَ إِلَى مَا لَا يَرِيبُكَ', text: '"Leave what makes you doubt for what does not make you doubt."', source: 'Tirmidhi 2518 — Sahih', day: 'On Avoiding Doubt' },
  { arabic: 'الْبِرُّ حُسْنُ الْخُلُقِ', text: '"Righteousness is good character."', source: 'Sahih Muslim 2553', day: 'On Good Character' },
  { arabic: 'خَيْرُ الصَّدَقَةِ مَا كَانَ عَنْ ظَهْرِ غِنًى', text: '"The best charity is what is given from abundance."', source: 'Sahih Al-Bukhari 1426', day: 'On Charity' },
  { arabic: 'اتَّقِ دَعْوَةَ الْمَظْلُومِ', text: '"Fear the supplication of the oppressed — for there is no barrier between it and Allah."', source: 'Sahih Al-Bukhari 1496', day: 'On Justice' },
  { arabic: 'أَقِيمُوا الصُّفُوفَ فَإِنَّ إِقَامَةَ الصُّفُوفِ مِنْ تَمَامِ الصَّلَاةِ', text: '"Straighten the rows, for straightening the rows is part of the perfection of prayer."', source: 'Sahih Al-Bukhari 723', day: 'On Congregational Prayer' },
  { arabic: 'صَلَاةُ الْجَمَاعَةِ تَفْضُلُ صَلَاةَ الْفَذِّ بِسَبْعٍ وَعِشْرِينَ دَرَجَةً', text: '"Prayer in congregation is twenty-seven degrees superior to prayer performed alone."', source: 'Sahih Al-Bukhari 645', day: 'On Congregational Prayer' },
  { arabic: 'رَكْعَتَا الْفَجْرِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا', text: '"The two rak\'ahs of Fajr sunnah are better than the world and all it contains."', source: 'Sahih Muslim 725', day: 'On Fajr Sunnah' },
  { arabic: 'أَوَّلُ مَا يُحَاسَبُ بِهِ الْعَبْدُ يَوْمَ الْقِيَامَةِ الصَّلَاةُ', text: '"The first thing the servant will be held accountable for on the Day of Judgment is prayer."', source: 'Abu Dawud 864 · Tirmidhi 413 — Sahih', day: 'On Prayer' },
  { arabic: 'مَثَلُ الصَّلَوَاتِ الْخَمْسِ كَمَثَلِ نَهَرٍ جَارٍ', text: '"The parable of the five prayers is like a flowing river — he bathes in it five times a day."', source: 'Sahih Muslim 668', day: 'On Five Prayers' },
  { arabic: 'اقْرَءُوا الْقُرْآنَ فَإِنَّهُ يَأْتِي يَوْمَ الْقِيَامَةِ شَفِيعًا لِأَصْحَابِهِ', text: '"Recite the Quran, for it will come on the Day of Resurrection as an intercessor for its companions."', source: 'Sahih Muslim 804', day: 'On Quran Recitation' },
  { arabic: 'الَّذِي يَقْرَأُ الْقُرْآنَ وَهُوَ مَاهِرٌ بِهِ مَعَ السَّفَرَةِ الْكِرَامِ', text: '"One who recites the Quran proficiently will be with the noble righteous scribes (angels)."', source: 'Sahih Al-Bukhari 4937', day: 'On Quran Recitation' },
  { arabic: 'وَالَّذِي يَقْرَأُ الْقُرْآنَ وَيَتَتَعْتَعُ فِيهِ وَهُوَ عَلَيْهِ شَاقٌّ لَهُ أَجْرَانِ', text: '"One who recites the Quran with difficulty — for him is a double reward."', source: 'Sahih Al-Bukhari 4937', day: 'On Quran with Difficulty' },
  { arabic: 'مَنْ قَرَأَ حَرْفًا مِنْ كِتَابِ اللهِ فَلَهُ بِهِ حَسَنَةٌ', text: '"Whoever reads a letter from the Book of Allah has a good deed, and a good deed is multiplied tenfold."', source: 'Tirmidhi 2910 — Sahih', day: 'On Every Letter of Quran' },
  { arabic: 'مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ', text: '"Whoever Allah wishes good for, He grants him deep understanding of the religion."', source: 'Sahih Al-Bukhari 71', day: 'On Understanding Religion' },
  { arabic: 'الْعُلَمَاءُ وَرَثَةُ الأَنْبِيَاءِ', text: '"The scholars are the inheritors of the Prophets."', source: 'Abu Dawud 3641 — Sahih', day: 'On Scholars' },
  { arabic: 'فَضْلُ الْعَالِمِ عَلَى الْعَابِدِ كَفَضْلِ الْقَمَرِ عَلَى سَائِرِ الْكَوَاكِبِ', text: '"The virtue of a scholar over a worshipper is like the moon over the stars."', source: 'Abu Dawud 3641 — Sahih', day: 'On Knowledge vs Worship' },
  { arabic: 'الدُّنْيَا مَتَاعٌ وَخَيْرُ مَتَاعِهَا الْمَرْأَةُ الصَّالِحَةُ', text: '"The world is an enjoyment and the best enjoyment is a righteous woman."', source: 'Sahih Muslim 1467', day: 'On Marriage' },
  { arabic: 'خَيْرُكُمْ خَيْرُكُمْ لِأَهْلِهِ وَأَنَا خَيْرُكُمْ لِأَهْلِي', text: '"The best of you are those best to their families, and I am the best to my family."', source: 'Tirmidhi 3895 — Sahih', day: 'On Family' },
  { arabic: 'اسْتَوْصُوا بِالنِّسَاءِ خَيْرًا', text: '"Treat women well."', source: 'Sahih Al-Bukhari 3331', day: 'On Women' },
  { arabic: 'بَيْنَ الرَّجُلِ وَبَيْنَ الشِّرْكِ وَالْكُفْرِ تَرْكُ الصَّلَاةِ', text: '"Between a man and shirk and kufr is the abandonment of prayer."', source: 'Sahih Muslim 82', day: 'On Importance of Prayer' },
  { arabic: 'مَنْ قَامَ لَيْلَةَ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ', text: '"Whoever stands in prayer on Laylat al-Qadr out of faith and seeking reward, his past sins are forgiven."', source: 'Sahih Al-Bukhari 1901', day: 'On Laylat Al-Qadr' },
  { arabic: 'مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ', text: '"Whoever prays during Ramadan out of faith and hoping for reward, his previous sins will be forgiven."', source: 'Sahih Al-Bukhari 37', day: 'On Tarawih' },
  { arabic: 'فِي الْجَنَّةِ بَابٌ يُقَالُ لَهُ الرَّيَّانُ يَدْخُلُ مِنْهُ الصَّائِمُونَ', text: '"In Paradise there is a gate called Al-Rayyan through which those who fasted will enter."', source: 'Sahih Al-Bukhari 1896', day: 'On Fasting' },
  { arabic: 'لِلصَّائِمِ فَرْحَتَانِ يَفْرَحُهُمَا', text: '"The fasting person has two joys: one when he breaks his fast, and one when he meets his Lord."', source: 'Sahih Al-Bukhari 1904', day: 'On Fasting' },
  { arabic: 'مَانِعُ الزَّكَاةِ يُعَذَّبُ بِمَالِهِ يَوْمَ الْقِيَامَةِ', text: '"The one who withholds zakat will be punished by his wealth on the Day of Resurrection."', source: 'Sahih Al-Bukhari 1403', day: 'On Zakat' },
  { arabic: 'الْحَجُّ الْمَبْرُورُ لَيْسَ لَهُ جَزَاءٌ إِلَّا الْجَنَّةُ', text: '"An accepted Hajj has no reward except Paradise."', source: 'Sahih Al-Bukhari 1773', day: 'On Hajj' },
  { arabic: 'مَنْ حَجَّ فَلَمْ يَرْفُثْ وَلَمْ يَفْسُقْ رَجَعَ كَيَوْمِ وَلَدَتْهُ أُمُّهُ', text: '"Whoever performs Hajj without obscenity or wickedness returns like the day his mother gave birth to him."', source: 'Sahih Al-Bukhari 1521', day: 'On Hajj' },
  { arabic: 'لَا تُشَدُّ الرِّحَالُ إِلَّا إِلَى ثَلَاثَةِ مَسَاجِدَ', text: '"No journey should be made (specifically for worship) except to three mosques: Al-Masjid Al-Haram, my mosque, and Al-Masjid Al-Aqsa."', source: 'Sahih Al-Bukhari 1189', day: 'On The Three Mosques' },
  { arabic: 'الصَّوْمُ وَالْقُرْآنُ يَشْفَعَانِ لِلْعَبْدِ يَوْمَ الْقِيَامَةِ', text: '"Fasting and the Quran will intercede for the servant on the Day of Resurrection."', source: 'Ahmad 6626 — Sahih', day: 'On Fasting and Quran' },
  { arabic: 'مَنْ فَطَّرَ صَائِمًا كَانَ لَهُ مِثْلُ أَجْرِهِ', text: '"Whoever gives a fasting person food to break his fast will have a reward equal to his."', source: 'Tirmidhi 807 — Sahih', day: 'On Breaking Fast' },
  { arabic: 'مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ وَلَا وَصَبٍ وَلَا هَمٍّ حَتَّى الشَّوْكَةِ يُشَاكُهَا إِلَّا كَفَّرَ اللَّهُ بِهَا مِنْ خَطَايَاهُ', text: '"No fatigue, illness, sorrow, sadness, or distress — even the prick of a thorn — befalls a Muslim, except that Allah expiates his sins by it."', source: 'Sahih Al-Bukhari 5641', day: 'On Trials' },
  { arabic: 'عَجَبًا لِأَمْرِ الْمُؤْمِنِ إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ', text: '"How wonderful is the case of a believer — all his affairs are good. If he has good fortune, he is grateful; if afflicted, he is patient. Both are good for him."', source: 'Sahih Muslim 2999', day: 'On the Believer\'s Attitude' },
  { arabic: 'أَشَدُّ النَّاسِ بَلَاءً الأَنْبِيَاءُ ثُمَّ الأَمْثَلُ فَالأَمْثَلُ', text: '"The most severely tested are the Prophets, then the righteous, then those most like them."', source: 'Tirmidhi 2398 — Sahih', day: 'On Trials' },
  { arabic: 'إِنَّ عِظَمَ الْجَزَاءِ مَعَ عِظَمِ الْبَلَاءِ', text: '"The greatness of the reward is commensurate with the greatness of the trial."', source: 'Tirmidhi 2396 — Sahih', day: 'On Patience in Trials' },
  { arabic: 'حُفَّتِ الْجَنَّةُ بِالْمَكَارِهِ وَحُفَّتِ النَّارُ بِالشَّهَوَاتِ', text: '"Paradise is surrounded by difficulties and the Fire is surrounded by desires."', source: 'Sahih Muslim 2822', day: 'On Paradise and Its Price' },
  { arabic: 'أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ', text: '"The closest a servant is to his Lord is when he is in prostration."', source: 'Sahih Muslim 482', day: 'On Sujud' },
  { arabic: 'السِّوَاكُ مَطْهَرَةٌ لِلْفَمِ مَرْضَاةٌ لِلرَّبِّ', text: '"The siwak cleanses the mouth and pleases the Lord."', source: 'Al-Nasa\'i 5 — Sahih', day: 'On Cleanliness' },
  { arabic: 'كُلُّ أَمْرٍ ذِي بَالٍ لَا يُبْدَأُ فِيهِ بِبِسْمِ اللهِ فَهُوَ أَجْذَمُ', text: '"Every matter of importance that does not begin with Bismillah is deficient."', source: 'Ibn Majah 1894 — Hasan', day: 'On Bismillah' },
  { arabic: 'آكِلُ الرِّبَا وَمُؤْكِلُهُ وَكَاتِبُهُ وَشَاهِدَاهُ سَوَاءٌ', text: '"The one who consumes riba, the one who pays it, the one who records it, and the two witnesses — they are all equal in sin."', source: 'Sahih Muslim 1598', day: 'On Riba' },
  { arabic: 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ', text: '"O Allah, I seek refuge in You from anxiety and grief."', source: 'Sahih Al-Bukhari 2893', day: 'On Dua from Worry' },
  { arabic: 'سَيِّدُ الاسْتِغْفَارِ أَنْ تَقُولَ اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ', text: '"The master of seeking forgiveness is to say: O Allah, You are my Lord, there is no god but You. You created me and I am Your servant..."', source: 'Sahih Al-Bukhari 6306', day: 'On Sayyid Al-Istighfar' },
  { arabic: 'مَنْ عَادَ مَرِيضًا لَمْ يَزَلْ فِي خُرْفَةِ الْجَنَّةِ', text: '"Whoever visits a sick person is as if walking in the garden of Paradise."', source: 'Sahih Muslim 2568', day: 'On Visiting the Sick' },
  { arabic: 'لَا يَمُوتَنَّ أَحَدُكُمْ إِلَّا وَهُوَ يُحْسِنُ الظَّنَّ بِاللهِ', text: '"None of you should die except while having good expectations of Allah."', source: 'Sahih Muslim 2877', day: 'On Good Expectation of Allah' },
  { arabic: 'أَنَا عِنْدَ ظَنِّ عَبْدِي بِي', text: '"I am as My servant expects Me to be."', source: 'Sahih Al-Bukhari 7405', day: 'On Good Expectation of Allah' },
  { arabic: 'مَنْ آمَنَ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلَا يُؤْذِ جَارَهُ', text: '"Whoever believes in Allah and the Last Day should not harm his neighbor."', source: 'Sahih Al-Bukhari 6018', day: 'On Neighbors' },
  { arabic: 'مَا زَالَ جِبْرِيلُ يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ', text: '"Jibreel kept urging me to treat the neighbor well until I thought he would make him an heir."', source: 'Sahih Al-Bukhari 6014', day: 'On Neighbors' },
  { arabic: 'لَا يَدْخُلُ الْجَنَّةَ مَنْ لَا يَأْمَنُ جَارُهُ بَوَائِقَهُ', text: '"He will not enter Paradise whose neighbor is not safe from his harm."', source: 'Sahih Muslim 46', day: 'On Neighbors' },
  { arabic: 'مَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الآخِرِ فَلْيُكْرِمْ ضَيْفَهُ', text: '"Whoever believes in Allah and the Last Day, let him honor his guest."', source: 'Sahih Al-Bukhari 6018', day: 'On Hospitality' },
  { arabic: 'أَفْشُوا السَّلَامَ بَيْنَكُمْ', text: '"Spread the greeting of salam among yourselves."', source: 'Sahih Muslim 54', day: 'On Spreading Salam' },
  { arabic: 'لَا تَدْخُلُوا الْجَنَّةَ حَتَّى تُؤْمِنُوا وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا', text: '"You will not enter Paradise until you believe, and you will not believe until you love one another. Shall I tell you of something that if you do it, you will love one another? Spread salam."', source: 'Sahih Muslim 54', day: 'On Love and Salam' },
  { arabic: 'خَيْرُ الدُّعَاءِ دُعَاءُ يَوْمِ عَرَفَةَ', text: '"The best supplication is the supplication of the Day of Arafah."', source: 'Tirmidhi 3585 — Hasan', day: 'On Day of Arafah' },
  { arabic: 'مَا مِنْ يَوْمٍ أَكْثَرَ مِنْ أَنْ يُعْتِقَ اللَّهُ فِيهِ عَبِيدًا مِنَ النَّارِ مِنْ يَوْمِ عَرَفَةَ', text: '"There is no day on which Allah frees more servants from the Fire than the Day of Arafah."', source: 'Sahih Muslim 1348', day: 'On Arafah' },
  { arabic: 'صِيَامُ يَوْمِ عَرَفَةَ يُكَفِّرُ سَنَتَيْنِ', text: '"Fasting the Day of Arafah expiates sins of the previous year and the coming year."', source: 'Sahih Muslim 1162', day: 'On Fasting Arafah' },
  { arabic: 'مَا مِنْ أَيَّامٍ الْعَمَلُ الصَّالِحُ فِيهَا أَحَبُّ إِلَى اللهِ مِنْ هَذِهِ الأَيَّامِ', text: '"No good deeds are more beloved to Allah than those done in the first ten days of Dhul Hijjah."', source: 'Sahih Al-Bukhari 969', day: 'On First Ten Days of Dhul Hijjah' },
  { arabic: 'يَوْمُ عَاشُورَاءَ أَحْتَسِبُ عَلَى اللهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ', text: '"The Day of Ashura — I hope that Allah will expiate the previous year\'s sins."', source: 'Sahih Muslim 1162', day: 'On Ashura' },
  { arabic: 'مَنْ لَمْ يَدَعْ قَوْلَ الزُّورِ وَالْعَمَلَ بِهِ فَلَيْسَ لِلَّهِ حَاجَةٌ فِي أَنْ يَدَعَ طَعَامَهُ وَشَرَابَهُ', text: '"Whoever does not give up false speech — Allah has no need of his giving up food and drink."', source: 'Sahih Al-Bukhari 1903', day: 'On True Fasting' },
  { arabic: 'شَهْرُ رَمَضَانَ جُعِلَتْ فِيهِ أَبْوَابُ الْجَنَّةِ مُفَتَّحَةً', text: '"In the month of Ramadan the gates of Paradise are opened, the gates of Hell are closed, and the devils are chained."', source: 'Sahih Al-Bukhari 1899', day: 'On Ramadan' },
  { arabic: 'أَحَبُّ الأَسْمَاءِ إِلَى اللهِ عَبْدُ اللهِ وَعَبْدُ الرَّحْمَنِ', text: '"The names most beloved to Allah are Abdullah and Abdur-Rahman."', source: 'Sahih Muslim 2132', day: 'On Names' },
  { arabic: 'إِنَّ أَثْقَلَ شَيْءٍ يُوضَعُ فِي الْمِيزَانِ يَوْمَ الْقِيَامَةِ خُلُقٌ حَسَنٌ', text: '"The heaviest thing placed on the scale on the Day of Judgment is good character."', source: 'Abu Dawud 4799', day: 'On Character' },
  { arabic: 'لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يَكُونَ هَوَاهُ تَبَعًا لِمَا جِئْتُ بِهِ', text: '"None of you truly believes until his desires follow what I have brought."', source: 'Al-Nawawi\'s 40 Hadith — Sahih', day: 'On Following the Sunnah' },
  { arabic: 'تَرَكْتُ فِيكُمْ أَمْرَيْنِ لَنْ تَضِلُّوا مَا تَمَسَّكْتُمْ بِهِمَا كِتَابَ اللهِ وَسُنَّةَ نَبِيِّهِ', text: '"I have left among you two things — you will not go astray as long as you hold to them: the Book of Allah and the Sunnah of His Prophet."', source: 'Muwatta Malik — Sahih', day: 'On Quran and Sunnah' },
  { arabic: 'خَيْرُ الْقُرُونِ قَرْنِي ثُمَّ الَّذِينَ يَلُونَهُمْ', text: '"The best of generations is my generation, then those who come after them, then those who come after them."', source: 'Sahih Al-Bukhari 2652', day: 'On Best Generations' },
  { arabic: 'لَا تَسُبُّوا أَصْحَابِي', text: '"Do not abuse my Companions."', source: 'Sahih Al-Bukhari 3673', day: 'On Respecting Companions' },
  { arabic: 'مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ', text: '"Whoever obeys me has obeyed Allah, and whoever disobeys me has disobeyed Allah."', source: 'Sahih Al-Bukhari 7137', day: 'On Obedience to Prophet ﷺ' },
  { arabic: 'لَا طَاعَةَ لِمَخْلُوقٍ فِي مَعْصِيَةِ الْخَالِقِ', text: '"There is no obedience to a created being if it involves disobedience to the Creator."', source: 'Ahmad 1095 — Sahih', day: 'On Obedience to Allah First' },
  { arabic: 'إِيَّاكُمْ وَالْغِيبَةَ', text: '"Beware of backbiting — mentioning your brother with what he dislikes."', source: 'Sahih Muslim 2589', day: 'On Backbiting' },
  { arabic: 'مَجَالِسُ الذِّكْرِ رِيَاضُ الْجَنَّةِ', text: '"Gatherings of remembrance are the gardens of Paradise."', source: 'Tirmidhi 3510 — Sahih', day: 'On Circles of Dhikr' },
  { arabic: 'مَنْ سَرَّهُ أَنْ يَسْتَجِيبَ اللَّهُ لَهُ عِنْدَ الشَّدَائِدِ فَلْيُكْثِرِ الدُّعَاءَ فِي الرَّخَاءِ', text: '"Whoever wishes Allah to respond to him in difficulty — let him make abundant dua in ease."', source: 'Tirmidhi 3382 — Hasan', day: 'On Dua in Ease' },
  { arabic: 'لَيْسَ شَيْءٌ أَكْرَمَ عَلَى اللهِ مِنَ الدُّعَاءِ', text: '"There is nothing more noble before Allah than supplication."', source: 'Tirmidhi 3370 — Sahih', day: 'On Dua' },
  { arabic: 'مَنْ لَمْ يَدْعُ اللهَ غَضِبَ اللهُ عَلَيْهِ', text: '"Whoever does not supplicate to Allah, Allah becomes angry with him."', source: 'Tirmidhi 3373 — Sahih', day: 'On Importance of Dua' },
  { arabic: 'ادْعُوا اللَّهَ وَأَنْتُمْ مُوقِنُونَ بِالإِجَابَةِ', text: '"Supplicate to Allah while certain of being answered."', source: 'Tirmidhi 3479 — Hasan', day: 'On Dua with Certainty' },
  { arabic: 'يَسْتَجِيبُ اللَّهُ لِلْعَبْدِ مَا لَمْ يَسْتَعْجِلْ', text: '"Allah responds to the servant as long as he does not rush."', source: 'Sahih Al-Bukhari 6340', day: 'On Patience in Dua' },
  { arabic: 'إِنَّ رَبَّكُمْ يَنْزِلُ كُلَّ لَيْلَةٍ إِلَى السَّمَاءِ الدُّنْيَا', text: '"Your Lord descends every night to the lowest heaven and calls: Who is supplicating to Me that I may answer him?"', source: 'Sahih Al-Bukhari 1145', day: 'On Night Supplication' },
  { arabic: 'ثَلَاثُ دَعَوَاتٍ مُسْتَجَابَاتٌ: دَعْوَةُ الْوَالِدِ وَدَعْوَةُ الْمَظْلُومِ وَدَعْوَةُ الْمُسَافِرِ', text: '"Three supplications are answered: the supplication of the parent, the oppressed, and the traveler."', source: 'Abu Dawud 1536 — Hasan', day: 'On Answered Supplications' },
  { arabic: 'دَعَوَاتُ الأَخِ لِأَخِيهِ بِظَهْرِ الْغَيْبِ مُسْتَجَابَةٌ', text: '"A man\'s supplication for his brother in his absence is answered."', source: 'Sahih Muslim 2733', day: 'On Supplication for Others' },
  { arabic: 'مَنْ أَكْثَرَ مِنَ الاسْتِغْفَارِ جَعَلَ اللَّهُ لَهُ مِنْ كُلِّ ضِيقٍ مَخْرَجًا', text: '"Whoever makes much istighfar — Allah makes for him a way out of every difficulty and grants him sustenance from where he did not expect."', source: 'Abu Dawud 1518 — Sahih', day: 'On Istighfar' },
  { arabic: 'إِنِّي لَأَسْتَغْفِرُ اللَّهَ فِي الْيَوْمِ مِائَةَ مَرَّةٍ', text: '"I seek forgiveness from Allah one hundred times every day."', source: 'Sahih Muslim 2702', day: 'On Daily Istighfar' },
  { arabic: 'التَّوْبَةُ تَجُبُّ مَا قَبْلَهَا', text: '"Repentance erases what came before it."', source: 'Sahih Muslim 121', day: 'On Repentance' },
  { arabic: 'كُلُّ بَنِي آدَمَ خَطَّاءٌ وَخَيْرُ الْخَطَّائِينَ التَّوَّابُونَ', text: '"Every son of Adam sins, and the best of sinners are those who repent."', source: 'Tirmidhi 2499 — Hasan', day: 'On Repentance' },
  { arabic: 'إِنَّ اللَّهَ يَبْسُطُ يَدَهُ بِاللَّيْلِ لِيَتُوبَ مُسِيءُ النَّهَارِ', text: '"Allah extends His hand at night to accept repentance from the one who sinned during the day."', source: 'Sahih Muslim 2759', day: 'On Repentance' },
  { arabic: 'مَنْ قَالَ سُبْحَانَ اللهِ وَبِحَمْدِهِ فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ', text: '"Whoever says SubhanAllahi wa bihamdihi 100 times in a day — his sins are wiped away even if they were like the foam of the sea."', source: 'Sahih Al-Bukhari 6405', day: 'On SubhanAllah' },
  { arabic: 'أَحَبُّ الْكَلَامِ إِلَى اللهِ أَرْبَعٌ: سُبْحَانَ اللهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللهُ، وَاللهُ أَكْبَرُ', text: '"The most beloved speech to Allah is four: SubhanAllah, Alhamdulillah, La ilaha illallah, and Allahu Akbar."', source: 'Sahih Muslim 2137', day: 'On Best Words' },
  { arabic: 'لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ كَنْزٌ مِنْ كُنُوزِ الْجَنَّةِ', text: '"La hawla wa la quwwata illa billah is a treasure from the treasures of Paradise."', source: 'Sahih Al-Bukhari 4205', day: 'On La Hawla' },
  { arabic: 'مَا يَزَالُ الْبَلَاءُ بِالْمُؤْمِنِ حَتَّى يَلْقَى اللَّهَ وَلَيْسَ عَلَيْهِ خَطِيئَةٌ', text: '"Trials continue to afflict the believer until he meets Allah with no sin upon him."', source: 'Tirmidhi 2399 — Sahih', day: 'On Trials Purifying the Believer' },
  { arabic: 'إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي', text: '"Inna lillahi wa inna ilayhi raji\'un — O Allah, reward me in my calamity and give me better than it."', source: 'Sahih Muslim 918', day: 'On Inna Lillahi' },
  { arabic: 'يَا غُلَامُ إِنِّي أُعَلِّمُكَ كَلِمَاتٍ احْفَظِ اللَّهَ يَحْفَظْكَ', text: '"O young man, I will teach you words: Guard Allah and Allah will guard you. Guard Allah and you will find Him in front of you."', source: 'Tirmidhi 2516 — Sahih', day: 'On Guarding Allah\'s Commands' },
  { arabic: 'إِذَا سَأَلْتَ فَاسْأَلِ اللَّهَ وَإِذَا اسْتَعَنْتَ فَاسْتَعِنْ بِاللَّهِ', text: '"When you ask, ask Allah. When you seek help, seek Allah\'s help."', source: 'Tirmidhi 2516', day: 'On Asking Only Allah' },
  { arabic: 'لَوْ كُنْتُمْ تَوَكَّلُونَ عَلَى اللَّهِ حَقَّ تَوَكُّلِهِ لَرَزَقَكُمْ كَمَا يَرْزُقُ الطَّيْرَ', text: '"If you truly relied on Allah as He deserves, He would provide for you as He provides for the birds — they leave hungry and return full."', source: 'Tirmidhi 2344 — Sahih', day: 'On Tawakkul' },
  { arabic: 'اعْلَمْ أَنَّ النَّصْرَ مَعَ الصَّبْرِ وَأَنَّ الْفَرَجَ مَعَ الْكَرْبِ وَأَنَّ مَعَ الْعُسْرِ يُسْرًا', text: '"Know that victory comes with patience, relief comes with hardship, and with every difficulty comes ease."', source: 'Tirmidhi 2516 — Sahih', day: 'On Hope' },
  { arabic: 'مَنْ قَرَأَ آيَةَ الْكُرْسِيِّ إِذَا أَوَى إِلَى فِرَاشِهِ حَفِظَهُ اللَّهُ', text: '"Whoever reads Ayat al-Kursi when he goes to bed — Allah will protect him and no devil will come near him until morning."', source: 'Sahih Al-Bukhari 2311', day: 'On Ayat Al-Kursi before Sleep' },
  { arabic: 'يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ', text: '"O Ever-Living, O Self-Sustaining — by Your mercy I seek relief."', source: 'Tirmidhi 3524 — Sahih', day: 'On Dua in Distress' },
  { arabic: 'أَكْثِرُوا مِنْ ذِكْرِ هَاذِمِ اللَّذَّاتِ', text: '"Increase in the remembrance of the destroyer of pleasures — death."', source: 'Tirmidhi 2307 — Sahih', day: 'On Remembering Death' },
  { arabic: 'حُسْنُ الظَّنِّ مِنْ حُسْنِ الْعِبَادَةِ', text: '"Having good thoughts of Allah is part of excellent worship."', source: 'Abu Dawud 4993 — Hasan', day: 'On Good Thoughts of Allah' },
  { arabic: 'وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ', text: '"When My servants ask you about Me — I am near. I respond to the call of the one who calls on Me."', source: 'Quran 2:186', day: 'On Allah\'s Nearness' },
  { arabic: 'وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ الْوَرِيدِ', text: '"And We are closer to him than his jugular vein."', source: 'Quran 50:16', day: 'On Allah\'s Closeness' },
  { arabic: 'حُسْنُ الْعِبَادَةِ أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ', text: '"The excellence of worship is that you worship Allah as if you see Him — and if you do not see Him, surely He sees you."', source: 'Sahih Al-Bukhari 50', day: 'On Ihsan in Worship' },
  { arabic: 'إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ', text: '"Indeed, good deeds wipe away evil deeds."', source: 'Quran 11:114', day: 'On Good Deeds Erasing Bad' },
  { arabic: 'أَفْضَلُ الصِّيَامِ بَعْدَ رَمَضَانَ شَهْرُ اللَّهِ الْمُحَرَّمُ', text: '"The best fasting after Ramadan is the month of Allah — Muharram."', source: 'Sahih Muslim 1163', day: 'On Voluntary Fasting' },
  { arabic: 'مَنْ أَصْبَحَ مِنْكُمْ آمِنًا فِي سِرْبِهِ مُعَافًى فِي جَسَدِهِ عِنْدَهُ قُوتُ يَوْمِهِ فَكَأَنَّمَا حِيزَتْ لَهُ الدُّنْيَا', text: '"Whoever wakes up secure in his dwelling, healthy in his body, and has food for the day — it is as if the whole world has been gathered for him."', source: 'Tirmidhi 2346 — Sahih', day: 'On Gratitude' },
  { arabic: 'ابْدَأْ بِمَنْ تَعُولُ', text: '"Begin with those who are under your care."', source: 'Sahih Al-Bukhari 5356', day: 'On Responsibility' },
  { arabic: 'مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُصِبْ مِنْهُ', text: '"Whomever Allah intends good for, He afflicts him."', source: 'Sahih Al-Bukhari 5645', day: 'On Trials as Signs of Good' },
  { arabic: 'الْمُسْتَشَارُ مُؤْتَمَنٌ', text: '"The one who is consulted is in a position of trust."', source: 'Abu Dawud 5128 · Tirmidhi 2823', day: 'On Giving Advice' },
  { arabic: 'مَنْ قَالَ حِينَ يُصْبِحُ وَحِينَ يُمْسِي بِسْمِ اللهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ', text: '"Whoever says in the morning and evening: \'In the name of Allah, with whose name nothing can cause harm\' — nothing will harm him."', source: 'Abu Dawud 5088 — Sahih', day: 'On Protection Dhikr' },
  { arabic: 'مَنْ قَالَ لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ مِائَةَ مَرَّةٍ', text: '"Whoever says La ilaha illallah wahdahu la sharika lahu 100 times — it is as if he freed ten slaves, 100 good deeds are written for him..."', source: 'Sahih Al-Bukhari 3293', day: 'On La Ilaha Illallah' },
  { arabic: 'مَنْ قَالَ سُبْحَانَ اللهِ الْعَظِيمِ وَبِحَمْدِهِ غُرِسَتْ لَهُ نَخْلَةٌ فِي الْجَنَّةِ', text: '"Whoever says SubhanAllah al-Adhimi wa bihamdihi — a palm tree is planted for him in Paradise."', source: 'Tirmidhi 3464 — Sahih', day: 'On Planting Trees in Paradise' },
  { arabic: 'لَأَنْ أَقُولَ سُبْحَانَ اللهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللهُ وَاللهُ أَكْبَرُ أَحَبُّ إِلَيَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ', text: '"To say SubhanAllah, Alhamdulillah, La ilaha illallah, and Allahu Akbar is more beloved to me than all that the sun has risen upon."', source: 'Sahih Muslim 2695', day: 'On Value of Dhikr' },
  { arabic: 'مَنْ قَرَأَ سُورَةَ الْكَهْفِ فِي يَوْمِ الْجُمُعَةِ أَضَاءَ لَهُ مِنَ النُّورِ مَا بَيْنَ الْجُمُعَتَيْنِ', text: '"Whoever recites Surah Al-Kahf on Friday, a light will shine for him between the two Fridays."', source: 'Al-Hakim — Sahih by Al-Albani', day: 'On Surah Al-Kahf' },
  { arabic: 'إِنَّ يَوْمَ الْجُمُعَةِ يَوْمٌ عَظِيمٌ وَفِيهِ سَاعَةٌ لَا يُوَافِقُهَا عَبْدٌ مُسْلِمٌ يَسْأَلُ اللهَ إِلَّا أَعْطَاهُ', text: '"Friday is a great day, and within it is an hour in which a Muslim does not ask Allah for anything except that He gives it to him."', source: 'Sahih Al-Bukhari 893', day: 'On Friday' },
  { arabic: 'أَكْثِرُوا الصَّلَاةَ عَلَيَّ يَوْمَ الْجُمُعَةِ وَلَيْلَةَ الْجُمُعَةِ', text: '"Send abundant blessings upon me on Fridays and the night before Friday."', source: 'Al-Bayhaqi — Sahih by Al-Albani', day: 'On Friday Salah upon Prophet ﷺ' },
  { arabic: 'كَفَى بِالْمَرْءِ إِثْمًا أَنْ يُحَدِّثَ بِكُلِّ مَا سَمِعَ', text: '"It is enough sin for a person to narrate everything he hears."', source: 'Sahih Muslim — Muqaddimah', day: 'On Verifying News' },
  { arabic: 'عَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ', text: '"Follow my Sunnah and the Sunnah of the rightly-guided caliphs after me."', source: 'Abu Dawud 4607 · Tirmidhi 2676', day: 'On Following Sunnah' },
  { arabic: 'إِنَّ مِنَ الشِّعْرِ لَحِكْمَةً', text: '"Indeed some poetry contains wisdom."', source: 'Sahih Al-Bukhari 6145', day: 'On Wisdom' },
  { arabic: 'وَفِي السَّمَاءِ رِزْقُكُمْ وَمَا تُوعَدُونَ', text: '"In the heaven is your provision and what you are promised."', source: 'Quran 51:22', day: 'On Rizq from Allah' },
  { arabic: 'لَنْ تَمُوتَ نَفْسٌ حَتَّى تَسْتَوْفِيَ أَجَلَهَا وَرِزْقَهَا', text: '"No soul will die until it has received its complete lifespan and sustenance."', source: 'Ibn Majah 2144 — Sahih', day: 'On Rizq and Ajal' },
  { arabic: 'الصِّدْقُ يَهْدِي إِلَى الْجَنَّةِ وَإِنَّ الرَّجُلَ يَصْدُقُ حَتَّى يُكْتَبَ عِنْدَ اللهِ صِدِّيقًا', text: '"Truthfulness leads to Paradise and a man keeps being truthful until he is written with Allah as a Siddiq."', source: 'Sahih Al-Bukhari 6094', day: 'On Truthfulness' },
  { arabic: 'وَلَا تَيْأَسُوا مِنْ رَوْحِ اللَّهِ إِنَّهُ لَا يَيْأَسُ مِنْ رَوْحِ اللَّهِ إِلَّا الْقَوْمُ الْكَافِرُونَ', text: '"Do not despair of the mercy of Allah — indeed no one despairs of Allah\'s mercy except the disbelieving people."', source: 'Quran 12:87', day: 'On Hope in Allah' },
  { arabic: 'وَهُوَ مَعَكُمْ أَيْنَمَا كُنتُمْ', text: '"And He is with you wherever you are."', source: 'Quran 57:4', day: 'On Allah Being with You' },
  { arabic: 'مَنْ قَرَأَ آيَةَ الْكُرْسِيِّ دُبُرَ كُلِّ صَلَاةٍ لَمْ يَمْنَعْهُ مِنْ دُخُولِ الْجَنَّةِ إِلَّا أَنْ يَمُوتَ', text: '"Whoever recites Ayat al-Kursi after every prayer — nothing prevents him from entering Paradise except death."', source: 'Al-Nasa\'i — Sahih by Al-Albani', day: 'On Ayat Al-Kursi' },
  { arabic: 'الصَّلَاةُ فِي مَسْجِدِي هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ', text: '"A prayer in my mosque is better than a thousand prayers elsewhere."', source: 'Sahih Al-Bukhari 1190', day: 'On Masjid Al-Nabawi' },
  { arabic: 'مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ', text: '"What is between my house and my pulpit is one of the gardens of Paradise."', source: 'Sahih Al-Bukhari 1196', day: 'On Prophet\'s Mosque' },
  { arabic: 'مَنْ قَرَأَ الْمُعَوِّذَتَيْنِ حِينَ يُمْسِي وَحِينَ يُصْبِحُ كَفَتَاهُ مِنْ كُلِّ شَيْءٍ', text: '"Whoever recites Al-Mu\'awwidhatain in the morning and evening — they are sufficient protection against everything."', source: 'Abu Dawud 5082 — Sahih', day: 'On Morning and Evening Surahs' },
  { arabic: 'مَنْ قَامَ بِعَشْرِ آيَاتٍ لَمْ يُكْتَبْ مِنَ الْغَافِلِينَ', text: '"Whoever stands in prayer with ten verses will not be written among the heedless."', source: 'Abu Dawud 1398 — Sahih', day: 'On Night Prayer' },
  { arabic: 'أَفْضَلُ الصَّلَاةِ بَعْدَ الْفَرِيضَةِ صَلَاةُ اللَّيْلِ', text: '"The best prayer after the obligatory is the night prayer."', source: 'Sahih Muslim 1163', day: 'On Tahajjud' },
  { arabic: 'يَنْزِلُ رَبُّنَا كُلَّ لَيْلَةٍ إِلَى السَّمَاءِ الدُّنْيَا حِينَ يَبْقَى ثُلُثُ اللَّيْلِ الْآخِرُ', text: '"Our Lord descends every night in the last third of the night and says: Who is asking of Me? Who is calling Me? Who seeks My forgiveness?"', source: 'Sahih Al-Bukhari 1145', day: 'On Last Third of Night' },
  { arabic: 'مَنْ أَدْرَكَ رَكْعَةً مِنَ الصُّبْحِ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَ الصُّبْحَ', text: '"Whoever catches one rak\'ah of Fajr before the sun rises has caught Fajr."', source: 'Sahih Al-Bukhari 579', day: 'On Catching Fajr' },
  { arabic: 'مَنْ صَلَّى الصُّبْحَ فَهُوَ فِي ذِمَّةِ اللهِ', text: '"Whoever prays Fajr is under the protection of Allah."', source: 'Sahih Muslim 657', day: 'On Fajr Prayer' },
  { arabic: 'لَوْ يَعْلَمُونَ مَا فِي الْعَتَمَةِ وَالصُّبْحِ لَأَتَوْهُمَا وَلَوْ حَبْوًا', text: '"If they knew what is in Isha and Fajr, they would come to them even crawling."', source: 'Sahih Al-Bukhari 657', day: 'On Fajr and Isha' },
  { arabic: 'مَنْ قَرَأَ قُلْ هُوَ اللهُ أَحَدٌ عَشْرَ مَرَّاتٍ بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ', text: '"Whoever recites Qul Huwa Allahu Ahad ten times, Allah builds him a house in Paradise."', source: 'Ahmad — Sahih by Al-Albani', day: 'On Surah Al-Ikhlas' },
  { arabic: 'قُلْ هُوَ اللهُ أَحَدٌ تَعْدِلُ ثُلُثَ الْقُرْآنِ', text: '"Qul Huwa Allahu Ahad is equivalent to one-third of the Quran."', source: 'Sahih Al-Bukhari 5013', day: 'On Surah Al-Ikhlas' },
  { arabic: 'الْحَيَاءُ شُعْبَةٌ مِنَ الْإِيمَانِ', text: '"Modesty (haya) is a branch of faith."', source: 'Sahih Al-Bukhari 9', day: 'On Modesty' },
  { arabic: 'الْحَيَاءُ لَا يَأْتِي إِلَّا بِخَيْرٍ', text: '"Modesty brings nothing but good."', source: 'Sahih Al-Bukhari 6117', day: 'On Modesty' },
  { arabic: 'إِذَا لَمْ تَسْتَحْيِ فَاصْنَعْ مَا شِئْتَ', text: '"If you have no modesty, then do whatever you wish."', source: 'Sahih Al-Bukhari 3484', day: 'On Modesty' },
  { arabic: 'إِنَّ مِمَّا أَدْرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْأُولَى إِذَا لَمْ تَسْتَحْيِ فَافْعَلْ مَا شِئْتَ', text: '"Among the words the people have inherited from the early Prophets: If you feel no shame, do as you please."', source: 'Sahih Al-Bukhari 3484', day: 'On Prophetic Wisdom' },
  { arabic: 'إِنَّ الْعَبْدَ لَيَبْلُغُ بِحُسْنِ خُلُقِهِ دَرَجَةَ الصَّائِمِ الْقَائِمِ', text: '"A servant reaches by his good character the degree of one who fasts and prays at night."', source: 'Abu Dawud 4798 — Sahih', day: 'On Good Character' },
  { arabic: 'ثَقُلَ مِيزَانُ مَنْ يُعَامِلُ النَّاسَ وَلَا يَضُرُّهُمْ', text: '"Heavy in the scale is the one who deals with people without harming them."', source: 'Related narration', day: 'On Treating People Well' },
  { arabic: 'خَيْرُ الصَّدَقَةِ جُهْدُ الْمُقِلِّ', text: '"The best charity is the effort of the one who has little."', source: 'Abu Dawud 1677 — Sahih', day: 'On Giving from Little' },
  { arabic: 'الأَعْمَالُ بِالْخَوَاتِيمِ', text: '"Deeds are judged by their endings."', source: 'Sahih Al-Bukhari 6607', day: 'On Persisting in Good' },
  { arabic: 'مَنْ مَاتَ وَهُوَ يَعْلَمُ أَنَّهُ لَا إِلَهَ إِلَّا اللهُ دَخَلَ الْجَنَّةَ', text: '"Whoever dies knowing that there is no god but Allah will enter Paradise."', source: 'Sahih Muslim 26', day: 'On Tawhid' },
  { arabic: 'أَفْضَلُ الذِّكْرِ لَا إِلَهَ إِلَّا اللهُ', text: '"The best dhikr is La ilaha illallah."', source: 'Tirmidhi 3383 — Sahih', day: 'On La Ilaha Illallah' },
  { arabic: 'جَدِّدُوا إِيمَانَكُمْ', text: '"Renew your faith." They asked: how? He said: "Say La ilaha illallah."', source: 'Ahmad 8709 — Sahih', day: 'On Renewing Faith' },
  { arabic: 'مَنْ مَاتَ وَآخِرُ كَلَامِهِ لَا إِلَهَ إِلَّا اللهُ دَخَلَ الْجَنَّةَ', text: '"Whoever dies and his last words are La ilaha illallah will enter Paradise."', source: 'Abu Dawud 3116 — Sahih', day: 'On Last Words' },
  { arabic: 'لَقِّنُوا مَوْتَاكُمْ لَا إِلَهَ إِلَّا اللهُ', text: '"Prompt your dying ones to say La ilaha illallah."', source: 'Sahih Muslim 916', day: 'On Death' },
  { arabic: 'الْقَبْرُ أَوَّلُ مَنَازِلِ الآخِرَةِ', text: '"The grave is the first station of the Hereafter."', source: 'Tirmidhi 2308 — Hasan', day: 'On the Grave' },
  { arabic: 'احْفَظِ اللهَ تَجِدْهُ أَمَامَكَ', text: '"Guard the rights of Allah and you will find Him in front of you."', source: 'Tirmidhi 2516 — Sahih', day: 'On Taqwa' },
  { arabic: 'تَعَرَّفْ إِلَى اللهِ فِي الرَّخَاءِ يَعْرِفْكَ فِي الشِّدَّةِ', text: '"Acquaint yourself with Allah in times of ease and He will recognize you in times of hardship."', source: 'Ahmad 2803 — Sahih', day: 'On Knowing Allah' },
  { arabic: 'مَا أَصَابَ أَحَدًا قَطُّ هَمٌّ وَلَا حَزَنٌ فَقَالَ: اللَّهُمَّ إِنِّي عَبْدُكَ وَابْنُ عَبْدِكَ إِلَّا فَرَّجَ اللَّهُ عَنْهُ', text: '"No one is ever stricken with anxiety and says: O Allah, I am Your servant, son of Your servant — except that Allah removes his anxiety."', source: 'Ahmad 3704 — Sahih', day: 'On Dua for Grief' },
  { arabic: 'مَنْ تَعَلَّمَ بَابًا مِنَ الْعِلْمِ عَمِلَ بِهِ أَوْ لَمْ يَعْمَلْ كَانَ أَفْضَلَ مِنْ أَنْ يُصَلِّيَ أَلْفَ رَكْعَةٍ', text: '"Whoever learns a chapter of knowledge — whether he acts on it or not — it is better than praying one thousand rak\'ahs."', source: 'Ibn Majah 219 — Hasan', day: 'On Learning' },
  { arabic: 'مَنْ سُئِلَ عَنْ عِلْمٍ فَكَتَمَهُ أُلْجِمَ بِلِجَامٍ مِنْ نَارٍ', text: '"Whoever is asked about knowledge and conceals it will be bridled with a bridle of fire."', source: 'Abu Dawud 3658 — Sahih', day: 'On Sharing Knowledge' },
  { arabic: 'إِنَّ الرِّفْقَ لَا يَكُونُ فِي شَيْءٍ إِلَّا زَانَهُ', text: '"Gentleness is not in anything except it beautifies it."', source: 'Sahih Muslim 2594', day: 'On Gentleness' },
  { arabic: 'إِنَّ الْفُحْشَ وَالتَّفَحُّشَ لَيْسَا مِنَ الإِسْلَامِ فِي شَيْءٍ', text: '"Obscenity and deliberate obscene behavior have nothing to do with Islam."', source: 'Ahmad — Sahih', day: 'On Avoiding Obscenity' },
  { arabic: 'لَيْسَ الْمُؤْمِنُ بِالطَّعَّانِ وَلَا اللَّعَّانِ وَلَا الْفَاحِشِ وَلَا الْبَذِيءِ', text: '"A believer is not a fault-finder, not a curser, not obscene, and not indecent."', source: 'Tirmidhi 1977 — Sahih', day: 'On Believer\'s Speech' },
  { arabic: 'أَحَبُّ النَّاسِ إِلَى اللهِ أَنْفَعُهُمْ لِلنَّاسِ', text: '"The most beloved people to Allah are those most beneficial to people."', source: 'Al-Mu\'jam Al-Awsat — Sahih', day: 'On Being Beneficial' },
  { arabic: 'أَحَبُّ الأَعْمَالِ إِلَى اللهِ سُرُورٌ تُدْخِلُهُ عَلَى مُسْلِمٍ', text: '"The most beloved deeds to Allah are bringing joy to a Muslim."', source: 'Al-Mu\'jam Al-Awsat — Sahih', day: 'On Bringing Joy' },
  { arabic: 'لَا تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا', text: '"Never belittle any act of kindness, even meeting your brother with a cheerful face."', source: 'Sahih Muslim 2626', day: 'On Small Acts of Kindness' },
  { arabic: 'اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ', text: '"Protect yourself from the Fire even by giving half a date in charity."', source: 'Sahih Al-Bukhari 1417', day: 'On Charity' },
  { arabic: 'مَنْ أَطْعَمَ أَخَاهُ حَتَّى يُشْبِعَهُ وَسَقَاهُ مِنَ الْمَاءِ أَبْعَدَهُ اللَّهُ مِنَ النَّارِ', text: '"Whoever feeds his brother until he is full and gives him water to drink, Allah will distance him from the Fire."', source: 'Sahih Muslim 2569', day: 'On Feeding Others' },
  { arabic: 'الرَّجُلُ عَلَى دِينِ خَلِيلِهِ', text: '"A person follows the religion of his close friend — so look carefully at who you befriend."', source: 'Abu Dawud 4833 · Tirmidhi 2378 — Hasan', day: 'On Choosing Friends' },
  { arabic: 'مَثَلُ الْجَلِيسِ الصَّالِحِ وَالسَّوْءِ كَحَامِلِ الْمِسْكِ وَنَافِخِ الْكِيرِ', text: '"The example of a good companion and a bad companion is like one who carries musk and one who blows the furnace."', source: 'Sahih Al-Bukhari 5534', day: 'On Good Companions' },
  { arabic: 'الْمَرْءُ مَعَ مَنْ أَحَبَّ', text: '"A person will be with whom he loves."', source: 'Sahih Al-Bukhari 6168', day: 'On Love for the Righteous' },
  { arabic: 'أَوْثَقُ عُرَى الإِيمَانِ الْمُوَالَاةُ فِي اللهِ وَالْمُعَادَاةُ فِي اللهِ', text: '"The firmest handhold of faith is to love for the sake of Allah and to hate for the sake of Allah."', source: 'Ahmad 18524 — Sahih', day: 'On Love for Allah\'s Sake' },
  { arabic: 'ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ حَلَاوَةَ الإِيمَانِ', text: '"Three qualities — whoever has them will taste the sweetness of faith: loving Allah and His Messenger above all else, loving for Allah\'s sake, and hating returning to disbelief as one hates being cast into fire."', source: 'Sahih Al-Bukhari 16', day: 'On Sweetness of Faith' },
  { arabic: 'أَلَا أُخْبِرُكُمْ بِأَهْلِ الْجَنَّةِ كُلُّ ضَعِيفٍ مُتَضَعِّفٍ', text: '"Shall I tell you of the people of Paradise? Every humble person who is considered weak — yet if they swore by Allah, He would fulfill it."', source: 'Sahih Al-Bukhari 4918', day: 'On the Humble' },
  { arabic: 'أَلَا أُخْبِرُكُمْ بِأَهْلِ النَّارِ كُلُّ عُتُلٍّ جَوَّاظٍ مُسْتَكْبِرٍ', text: '"Shall I tell you of the people of the Fire? Every harsh, rude, arrogant person."', source: 'Sahih Al-Bukhari 4918', day: 'On Avoiding Arrogance' },
  { arabic: 'لَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ كِبْرٍ', text: '"No one who has an atom\'s weight of arrogance in his heart will enter Paradise."', source: 'Sahih Muslim 91', day: 'On Avoiding Pride' },
  { arabic: 'الْكِبْرُ بَطَرُ الْحَقِّ وَغَمْطُ النَّاسِ', text: '"Arrogance is rejecting the truth and belittling people."', source: 'Sahih Muslim 91', day: 'On Pride Defined' },
  { arabic: 'إِيَّاكُمْ وَالْحَسَدَ فَإِنَّ الْحَسَدَ يَأْكُلُ الْحَسَنَاتِ', text: '"Beware of envy, for envy devours good deeds just as fire devours wood."', source: 'Abu Dawud 4903 — Hasan', day: 'On Avoiding Envy' },
  { arabic: 'لَا تَبَاغَضُوا وَلَا تَحَاسَدُوا وَلَا تَدَابَرُوا', text: '"Do not hate one another, do not envy one another, do not turn your backs on one another — be brothers."', source: 'Sahih Al-Bukhari 6065', day: 'On Brotherhood' },
  { arabic: 'يُغْبَطُ الرَّجُلُ عَلَى عِلْمِهِ يُعَلِّمُهُ النَّاسَ', text: '"One deserves to be envied (in a positive sense) for knowledge he teaches people."', source: 'Sahih Al-Bukhari 73', day: 'On Teaching Knowledge' },
  { arabic: 'مَنْ كَتَمَ عِلْمًا نَافِعًا جَاءَ يَوْمَ الْقِيَامَةِ مُلْجَمًا بِنَارٍ', text: '"Whoever conceals beneficial knowledge will come on the Day of Judgment muzzled with fire."', source: 'Ahmad — Hasan', day: 'On Sharing Knowledge' },
  { arabic: 'بَلِّغُوا عَنِّي وَلَوْ آيَةً', text: '"Convey from me, even if it is one verse."', source: 'Sahih Al-Bukhari 3461', day: 'On Conveying the Deen' },
  { arabic: 'رَحِمَ اللَّهُ امْرَأً سَمِعَ مَقَالَتِي فَوَعَاهَا فَأَدَّاهَا كَمَا سَمِعَهَا', text: '"May Allah have mercy on one who hears my words, retains them, and conveys them as he heard them."', source: 'Tirmidhi 2657 — Sahih', day: 'On Conveying Hadith' },
  { arabic: 'نَضَّرَ اللَّهُ امْرَأً سَمِعَ مِنَّا شَيْئًا فَبَلَّغَهُ كَمَا سَمِعَهُ', text: '"May Allah make radiant one who hears something from us and conveys it as he heard it."', source: 'Tirmidhi 2656 — Sahih', day: 'On Spreading Knowledge' },
  { arabic: 'لَا يَشْكُرُ اللَّهَ مَنْ لَا يَشْكُرُ النَّاسَ', text: '"He does not thank Allah who does not thank people."', source: 'Abu Dawud 4811 · Tirmidhi 1954 — Sahih', day: 'On Gratitude to People' },
  { arabic: 'مَنْ صَنَعَ إِلَيْكُمْ مَعْرُوفًا فَكَافِئُوهُ', text: '"Whoever does you a favor, reward him. If you cannot, then pray for him."', source: 'Abu Dawud 1672 — Sahih', day: 'On Reciprocating Kindness' },
  { arabic: 'هَلْ جَزَاءُ الإِحْسَانِ إِلَّا الإِحْسَانُ', text: '"Is the reward of goodness anything but goodness?"', source: 'Quran 55:60', day: 'On Goodness' },
  { arabic: 'إِنَّ اللَّهَ يُحِبُّ إِذَا عَمِلَ أَحَدُكُمْ عَمَلًا أَنْ يُتْقِنَهُ', text: '"Allah loves that when one of you does a deed, he perfects it."', source: 'Al-Bayhaqi — Sahih by Al-Albani', day: 'On Excellence in Work' },
  { arabic: 'الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ وَأَحَبُّ إِلَى اللهِ مِنَ الْمُؤْمِنِ الضَّعِيفِ', text: '"The strong believer is better and more beloved to Allah than the weak believer, though both are good."', source: 'Sahih Muslim 2664', day: 'On Strength' },
  { arabic: 'وَفِي كُلٍّ خَيْرٌ', text: '"And in each there is good." (Speaking of strong and weak believers.)', source: 'Sahih Muslim 2664', day: 'On Every Believer Having Good' },
  { arabic: 'تَزَوَّجُوا فَإِنِّي مُكَاثِرٌ بِكُمُ الأُمَمَ يَوْمَ الْقِيَامَةِ', text: '"Marry, for I will be proud of your large numbers before the nations on the Day of Judgment."', source: 'Ibn Majah 1846 — Sahih', day: 'On Marriage' },
  { arabic: 'مَنْ رَزَقَهُ اللَّهُ امْرَأَةً صَالِحَةً فَقَدْ أَعَانَهُ عَلَى شَطْرِ دِينِهِ', text: '"Whoever Allah blesses with a righteous wife has been helped with half of his religion."', source: 'Al-Hakim — Sahih by Al-Albani', day: 'On Righteous Spouse' },
  { arabic: 'إِذَا أَتَاكُمْ مَنْ تَرْضَوْنَ دِينَهُ وَخُلُقَهُ فَزَوِّجُوهُ', text: '"If someone whose religion and character you approve of comes to you (for marriage), then marry to him."', source: 'Tirmidhi 1084 — Hasan', day: 'On Choosing a Spouse' },
  { arabic: 'أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا وَخِيَارُكُمْ خِيَارُكُمْ لِنِسَائِهِمْ', text: '"The most complete believers in faith are those with the best character, and the best of you are the best to their women."', source: 'Tirmidhi 1162 — Sahih', day: 'On Best to Wives' },
  { arabic: 'لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِجَارِهِ مَا يُحِبُّ لِنَفْسِهِ', text: '"None of you truly believes until he loves for his neighbor what he loves for himself."', source: 'Sahih Muslim 45', day: 'On Neighbors' },
  { arabic: 'كَفَى بِالْمَرْءِ شَرًّا أَنْ يُهِينَ أَخَاهُ الْمُسْلِمَ', text: '"It is enough evil for a person to humiliate his Muslim brother."', source: 'Sahih Muslim 2564', day: 'On Dignity of Muslims' },
  { arabic: 'الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَخْذُلُهُ وَلَا يَكْذِبُهُ وَلَا يَحْقِرُهُ', text: '"A Muslim is the brother of a Muslim — he does not let him down, lie to him, or belittle him."', source: 'Tirmidhi 1927 — Sahih', day: 'On Brotherhood' },
  { arabic: 'التَّقْوَى هَاهُنَا وَيُشِيرُ إِلَى صَدْرِهِ', text: '"Taqwa is here — pointing to his chest three times."', source: 'Sahih Muslim 2564', day: 'On Taqwa in the Heart' },
  { arabic: 'بِحَسْبِ امْرِئٍ مِنَ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ', text: '"It is enough evil for a person to belittle his Muslim brother."', source: 'Sahih Muslim 2564', day: 'On Belittling Others' },
  { arabic: 'كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ دَمُهُ وَمَالُهُ وَعِرْضُهُ', text: '"Every Muslim\'s blood, wealth, and honor are sacred to another Muslim."', source: 'Sahih Muslim 2564', day: 'On Sanctity of Muslim' },
  { arabic: 'انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا', text: '"Support your brother whether he is the oppressor or the oppressed." (By stopping him from oppressing.)', source: 'Sahih Al-Bukhari 2444', day: 'On Helping Your Brother' },
  { arabic: 'إِنَّ الشَّيْطَانَ مَعَ الْوَاحِدِ وَهُوَ مِنَ الاثْنَيْنِ أَبْعَدُ', text: '"Indeed Satan is with the lone person, and he is further from two."', source: 'Tirmidhi 2165 — Sahih', day: 'On Community' },
  { arabic: 'عَلَيْكُمْ بِالْجَمَاعَةِ وَإِيَّاكُمْ وَالْفُرْقَةَ', text: '"Adhere to the community and beware of division."', source: 'Tirmidhi 2165 — Sahih', day: 'On Unity' },
  { arabic: 'يَدُ اللَّهِ مَعَ الْجَمَاعَةِ', text: '"The hand of Allah is with the community."', source: 'Tirmidhi 2166 — Sahih', day: 'On Sticking Together' },
  { arabic: 'وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا دَامَ الْعَبْدُ فِي عَوْنِ أَخِيهِ', text: '"Allah is in the servant\'s aid as long as the servant is in the aid of his brother."', source: 'Sahih Muslim 2699', day: 'On Helping Each Other' },
  { arabic: 'مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ', text: '"Whoever points to a good deed will have a reward equal to the one who does it."', source: 'Sahih Muslim 1893', day: 'On Guiding to Good' },
  { arabic: 'مَنْ دَعَا إِلَى هُدًى كَانَ لَهُ مِنَ الأَجْرِ مِثْلُ أُجُورِ مَنِ اتَّبَعَهُ', text: '"Whoever calls to guidance will have a reward like the rewards of all who follow him."', source: 'Sahih Muslim 2674', day: 'On Calling to Good' },
  { arabic: 'مَنْ دَعَا إِلَى ضَلَالَةٍ كَانَ عَلَيْهِ مِنَ الإِثْمِ مِثْلُ إِثْمِ مَنِ اتَّبَعَهُ', text: '"Whoever calls to misguidance will bear a sin like the sins of all who follow him."', source: 'Sahih Muslim 2674', day: 'On Warning Against Leading Astray' },
  { arabic: 'مَنْ سَنَّ فِي الإِسْلَامِ سُنَّةً حَسَنَةً فَلَهُ أَجْرُهَا وَأَجْرُ مَنْ عَمِلَ بِهَا', text: '"Whoever establishes a good practice in Islam will have its reward and the reward of all who act on it."', source: 'Sahih Muslim 1017', day: 'On Setting Good Examples' },
  { arabic: 'إِيَّاكُمْ وَمُحْدَثَاتِ الأُمُورِ', text: '"Beware of newly invented matters (in religion)."', source: 'Abu Dawud 4607 — Sahih', day: 'On Innovation' },
  { arabic: 'اللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي هُوَ عِصْمَةُ أَمْرِي', text: '"O Allah, rectify for me my religion which is the safeguard of my affairs."', source: 'Sahih Muslim 2720', day: 'On Dua for Religion' },
  { arabic: 'وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي', text: '"And rectify for me my Hereafter which is my final destination."', source: 'Sahih Muslim 2720', day: 'On Dua for Hereafter' },
  { arabic: 'وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ', text: '"Make life an increase for me in every good, and make death a rest for me from every evil."', source: 'Sahih Muslim 2720', day: 'On Comprehensive Dua' },
  { arabic: 'إِنَّ لِرَبِّكُمْ فِي أَيَّامِ دَهْرِكُمْ نَفَحَاتٍ فَتَعَرَّضُوا لَهَا', text: '"In the days of your life there are divine breaths from your Lord — so expose yourself to them."', source: 'Al-Bayhaqi — Sahih by Al-Albani', day: 'On Divine Moments of Mercy' },
  { arabic: 'لَعَلَّ اللَّهَ اطَّلَعَ عَلَى أَهْلِ بَدْرٍ فَقَالَ اعْمَلُوا مَا شِئْتُمْ', text: '"Perhaps Allah looked at the people of Badr and said: Do as you wish, for I have forgiven you."', source: 'Sahih Al-Bukhari 3983', day: 'On Companions of Badr' },
  { arabic: 'مَنْ قَامَ بِعَشْرِ آيَاتٍ لَمْ يُكْتَبْ مِنَ الْغَافِلِينَ وَمَنْ قَامَ بِمِائَةِ آيَةٍ كُتِبَ مِنَ الْقَانِتِينَ', text: '"Whoever prays with ten verses will not be written among the heedless; whoever prays with one hundred verses will be written among the devout."', source: 'Abu Dawud 1398 — Sahih', day: 'On Night Prayer' },
  { arabic: 'لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي ظَاهِرِينَ عَلَى الْحَقِّ', text: '"A group from my Ummah will always remain established upon the truth, not harmed by those who oppose them."', source: 'Sahih Al-Bukhari 3641', day: 'On the Victorious Group' },
  { arabic: 'سَلُوا اللهَ الْعَافِيَةَ', text: '"Ask Allah for wellbeing (\'afiyah)."', source: 'Tirmidhi 3514', day: 'On Seeking Wellbeing' },
  { arabic: 'مَنْ لَقِيَ اللهَ لَا يُشْرِكُ بِهِ شَيْئًا دَخَلَ الْجَنَّةَ', text: '"Whoever meets Allah without having associated anything with Him will enter Paradise."', source: 'Sahih Al-Bukhari 129', day: 'On Tawhid and Jannah' },
  { arabic: 'مَنْ لَقِيَ اللهَ يُشْرِكُ بِهِ شَيْئًا دَخَلَ النَّارَ', text: '"Whoever meets Allah while associating partners with Him will enter the Fire."', source: 'Sahih Al-Bukhari 129', day: 'On Avoiding Shirk' },
  { arabic: 'إِنَّ الشِّرْكَ لَأَعْظَمُ الظُّلْمِ', text: '"Indeed shirk is the greatest injustice."', source: 'Quran 31:13', day: 'On Shirk' },
  { arabic: 'وَأَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَيُوَفِّيهِمْ أُجُورَهُمْ', text: '"As for those who believed and did righteous deeds, He will give them their rewards in full."', source: 'Quran 3:57', day: 'On Reward for Good Deeds' },
  { arabic: 'إِنَّ الصَّلَاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنكَرِ وَلَذِكْرُ اللَّهِ أَكْبَرُ', text: '"Indeed prayer prohibits immorality and wrongdoing, and the remembrance of Allah is greater."', source: 'Quran 29:45', day: 'On Prayer and Dhikr' },
  { arabic: 'وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ', text: '"I did not create the jinn and mankind except to worship Me."', source: 'Quran 51:56', day: 'On Purpose of Creation' },
  { arabic: 'وَإِن تَعُدُّوا نِعْمَتَ اللَّهِ لَا تُحْصُوهَا', text: '"And if you were to count the blessings of Allah, you could never enumerate them."', source: 'Quran 14:34', day: 'On Blessings of Allah' },
  { arabic: 'فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ', text: '"Remember Me and I will remember you. Be grateful to Me and do not be ungrateful."', source: 'Quran 2:152', day: 'On Dhikr and Shukr' },
  { arabic: 'وَلَلْآخِرَةُ خَيْرٌ لَّكَ مِنَ الْأُولَىٰ', text: '"And the Hereafter is better for you than the first (this world)."', source: 'Quran 93:4', day: 'On Valuing the Hereafter' },
  { arabic: 'أَيُحْسَبُ الْإِنسَانُ أَن يُتْرَكَ سُدًى', text: '"Does man think that he will be left to no purpose?"', source: 'Quran 75:36', day: 'On Accountability' },
  { arabic: 'كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ', text: '"Every soul shall taste death."', source: 'Quran 3:185', day: 'On Death' },
  { arabic: 'يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ', text: '"O you who believe, fear Allah as He deserves to be feared."', source: 'Quran 3:102', day: 'On True Taqwa' },
  { arabic: 'وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', text: '"Do not die except in a state of Islam."', source: 'Quran 3:102', day: 'On Dying as a Muslim' },
  { arabic: 'يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا', text: '"O you who believe, remember Allah with much remembrance."', source: 'Quran 33:41', day: 'On Abundant Dhikr' },
  { arabic: 'وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا', text: '"And exalt Him morning and evening."', source: 'Quran 33:42', day: 'On Morning and Evening Tasbih' },
  { arabic: 'هُوَ الَّذِي يُصَلِّي عَلَيْكُمْ وَمَلَائِكَتُهُ لِيُخْرِجَكُم مِّنَ الظُّلُمَاتِ إِلَى النُّورِ', text: '"It is He who sends His blessings upon you and His angels, to bring you out of darkness into light."', source: 'Quran 33:43', day: 'On Allah\'s Mercy' },
  { arabic: 'يَا أَيُّهَا النَّاسُ أَنتُمُ الْفُقَرَاءُ إِلَى اللَّهِ وَاللَّهُ هُوَ الْغَنِيُّ الْحَمِيدُ', text: '"O people, you are those in need of Allah, while Allah is the Free of need, the Praiseworthy."', source: 'Quran 35:15', day: 'On Human Need for Allah' },
  { arabic: 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً', text: '"Our Lord, do not let our hearts deviate after You have guided us, and grant us from Yourself mercy."', source: 'Quran 3:8', day: 'On Steadfastness' },
  { arabic: 'رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ', text: '"Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire."', source: 'Quran 2:201', day: 'On Best Dua' },
  { arabic: 'رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي', text: '"My Lord, expand for me my chest, and ease for me my task."', source: 'Quran 20:25-26', day: 'On Dua of Musa ﷺ' },
  { arabic: 'رَبِّ زِدْنِي عِلْمًا', text: '"My Lord, increase me in knowledge."', source: 'Quran 20:114', day: 'On Dua for Knowledge' },
  { arabic: 'رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالإِيمَانِ', text: '"Our Lord, forgive us and our brothers who preceded us in faith."', source: 'Quran 59:10', day: 'On Dua for All Believers' },
  { arabic: 'رَبَّنَا إِنَّنَا آمَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ النَّارِ', text: '"Our Lord, indeed we have believed, so forgive us our sins and protect us from the punishment of the Fire."', source: 'Quran 3:16', day: 'On Dua of the Faithful' },
  { arabic: 'رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ', text: '"Our Lord, pour upon us patience and plant firmly our feet and give us victory over the disbelieving people."', source: 'Quran 2:250', day: 'On Dua for Patience and Victory' },
  { arabic: 'رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا', text: '"Our Lord, grant us from among our wives and offspring comfort to our eyes and make us an example for the righteous."', source: 'Quran 25:74', day: 'On Dua for Family' },
  { arabic: 'الَّذِي خَلَقَنِي فَهُوَ يَهْدِينِ وَالَّذِي هُوَ يُطْعِمُنِي وَيَسْقِينِ', text: '"It is He who created me and He guides me. And it is He who feeds me and gives me drink."', source: 'Quran 26:78-79', day: 'On Reliance on Allah' },
  { arabic: 'وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ', text: '"And when I am ill, it is He who cures me."', source: 'Quran 26:80', day: 'On Healing from Allah' },
  { arabic: 'وَالَّذِي أَطْمَعُ أَن يَغْفِرَ لِي خَطِيئَتِي يَوْمَ الدِّينِ', text: '"And He who I hope will forgive me my sins on the Day of Recompense."', source: 'Quran 26:82', day: 'On Hope in Allah\'s Forgiveness' },
  { arabic: 'رَبِّ إِنِّي لِمَا أَنزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ', text: '"My Lord, indeed I am, for whatever good You would send down to me, in need."', source: 'Quran 28:24', day: 'On Humility Before Allah' },
  { arabic: 'رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ', text: '"Our Lord, do not burden us with what we do not have the strength to bear."', source: 'Quran 2:286', day: 'On Asking for Ease' },
  { arabic: 'لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا', text: '"Allah does not burden a soul beyond that it can bear."', source: 'Quran 2:286', day: 'On Allah\'s Justice' },
  { arabic: 'وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ', text: '"Whoever fears Allah — He will make for him a way out and provide for him from where he did not expect."', source: 'Quran 65:2-3', day: 'On Taqwa Opens Doors' },
  { arabic: 'وَمَن يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ', text: '"And whoever relies upon Allah — then He is sufficient for him."', source: 'Quran 65:3', day: 'On Tawakkul' },
  { arabic: 'إِنَّ اللَّهَ بَالِغُ أَمْرِهِ قَدْ جَعَلَ اللَّهُ لِكُلِّ شَيْءٍ قَدْرًا', text: '"Indeed Allah will accomplish His purpose. Allah has already set for everything a decreed extent."', source: 'Quran 65:3', day: 'On Divine Decree' },
  { arabic: 'فَإِنَّ مَعَ الْعُسْرِ يُسْرًا إِنَّ مَعَ الْعُسْرِ يُسْرًا', text: '"For indeed with every hardship comes ease. Indeed with every hardship comes ease." (Repeated twice.)', source: 'Quran 94:5-6', day: 'On Ease After Hardship' },
  { arabic: 'خَيْرُ الْكَلَامِ كَلَامُ اللهِ', text: '"The best of speech is the speech of Allah (the Quran)."', source: 'Sahih Al-Bukhari 5017', day: 'On the Quran' },
  { arabic: 'وَخَيْرُ الْهَدْيِ هَدْيُ مُحَمَّدٍ', text: '"And the best of guidance is the guidance of Muhammad ﷺ."', source: 'Sahih Muslim 867', day: 'On Following the Prophet ﷺ' },
  { arabic: 'وَشَرُّ الأُمُورِ مُحْدَثَاتُهَا', text: '"And the worst of matters are innovations."', source: 'Sahih Muslim 867', day: 'On Innovation' },
  { arabic: 'الدُّنْيَا سِجْنُ الْمُؤْمِنِ وَجَنَّةُ الْكَافِرِ', text: '"The world is a prison for the believer and a paradise for the disbeliever."', source: 'Sahih Muslim 2956', day: 'On Dunya' },
  { arabic: 'إِذَا رَأَيْتُمُ الرَّجُلَ يَعْتَادُ الْمَسْجِدَ فَاشْهَدُوا لَهُ بِالإِيمَانِ', text: '"When you see a man regularly attending the mosque, bear witness to his faith."', source: 'Tirmidhi 2617 — Sahih', day: 'On Attachment to Masjid' },
  { arabic: 'مَنِ احْتَكَرَ فَهُوَ خَاطِئٌ', text: '"Whoever hoards goods (to harm people) is a sinner."', source: 'Sahih Muslim 1605', day: 'On Avoiding Hoarding' },
  { arabic: 'الْبَائِعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا', text: '"Both parties in a transaction have the option to cancel as long as they have not separated."', source: 'Sahih Al-Bukhari 2079', day: 'On Honest Trade' },
  { arabic: 'نِعْمَ الْعَبْدُ عَبْدُ اللهِ هُوَ إِذَا تَهَجَّدَ مِنَ اللَّيْلِ', text: '"What a good servant is Abdullah — if only he prayed the night prayer." (Referring to Ibn Umar.)', source: 'Sahih Al-Bukhari 1122', day: 'On Tahajjud' },
  { arabic: 'أَلَا كُلُّكُمْ رَاعٍ', text: '"Indeed every one of you is a caretaker, and every caretaker will be asked about his flock."', source: 'Sahih Al-Bukhari 2554', day: 'On Leadership and Responsibility' },
  { arabic: 'وَأَفْضَلُ الصَّدَقَةِ عَلَى ذِي الرَّحِمِ الْكَاشِحِ', text: '"The best charity is to a relative who is hostile toward you."', source: 'Ahmad — Sahih', day: 'On Charity to Relatives' },
  { arabic: 'إِذَا خَرَجَ الرَّجُلُ مِنْ بَيْتِهِ إِلَى الْمَسْجِدِ كُتِبَ لَهُ بِكُلِّ خَطْوَةٍ حَسَنَةٌ', text: '"When a man leaves his house to the mosque, a good deed is written for him with every step."', source: 'Sahih Muslim 666', day: 'On Walking to Masjid' },
  { arabic: 'مَنِ اغْتَسَلَ يَوْمَ الْجُمُعَةِ وَلَبِسَ أَحْسَنَ مَا عِنْدَهُ', text: '"Whoever takes a bath on Friday and wears his best clothing..."', source: 'Abu Dawud 343 — Sahih', day: 'On Friday Preparation' },
  { arabic: 'اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي', text: '"O Allah, You are Pardoning and You love to pardon, so pardon me."', source: 'Tirmidhi 3513 — Sahih', day: 'On Laylat Al-Qadr Dua' },
  { arabic: 'الْحَيَاءُ خَيْرٌ كُلُّهُ', text: '"Modesty is entirely good."', source: 'Sahih Muslim 37', day: 'On Modesty' },
  { arabic: 'إِيَّاكُمْ وَالتَّكَبُّرَ', text: '"Beware of arrogance."', source: 'Various Hadith', day: 'On Avoiding Pride' },
  { arabic: 'مَا مِنْكُمْ مِنْ أَحَدٍ إِلَّا سَيُكَلِّمُهُ رَبُّهُ لَيْسَ بَيْنَهُ وَبَيْنَهُ تَرْجُمَانٌ', text: '"There is none of you except that his Lord will speak to him directly — with no translator between them."', source: 'Sahih Al-Bukhari 7512', day: 'On Meeting Allah' },
  { arabic: 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعِفَّةَ وَالْغِنَى', text: '"O Allah, I ask You for guidance, piety, chastity, and self-sufficiency."', source: 'Sahih Muslim 2721', day: 'On Best Things to Ask For' },
  { arabic: 'الْبَرَكَةُ مَعَ أَكَابِرِكُمْ', text: '"Blessing is with your elders."', source: 'Ibn Hibban — Sahih', day: 'On Respecting Elders' },
  { arabic: 'وَقِّرُوا الْكِبَارَ فَإِنَّ تَوْقِيرَ الْكِبَارِ مِنْ تَوْقِيرِ اللهِ', text: '"Honor the elderly, for honoring the elderly is part of honoring Allah."', source: 'Abu Dawud 4843 — Hasan', day: 'On Respecting Elders' },
  { arabic: 'لَيْسَ مِنَّا مَنْ لَمْ يَرْحَمْ صَغِيرَنَا وَيُوَقِّرْ كَبِيرَنَا', text: '"He is not one of us who does not show mercy to our young and honor to our elderly."', source: 'Abu Dawud 4943 · Tirmidhi 1919 — Sahih', day: 'On Young and Old' },
  { arabic: 'أَكْرِمُوا الشُّهَدَاءَ', text: '"Honor the martyrs."', source: 'Various narrations', day: 'On Martyrs' },
  { arabic: 'لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ مِنْ أَحَدِكُمْ', text: '"Allah is more pleased with the repentance of His servant than one of you finding his lost camel."', source: 'Sahih Al-Bukhari 6309', day: 'On Joy of Repentance' },
  { arabic: 'لَوْ لَمْ تُذْنِبُوا لَذَهَبَ اللَّهُ بِكُمْ وَجَاءَ بِقَوْمٍ يُذْنِبُونَ فَيَسْتَغْفِرُونَ', text: '"If you did not sin, Allah would have replaced you with people who sin and then seek forgiveness."', source: 'Sahih Muslim 2749', day: 'On Repentance' },
  { arabic: 'وَإِنَّ كُلَّ أَمَتِي يَدْخُلُونَ الْجَنَّةَ إِلَّا مَنْ أَبَى', text: '"All of my Ummah will enter Paradise except those who refuse." They asked: who refuses? He said: "Whoever obeys me enters Paradise and whoever disobeys me has refused."', source: 'Sahih Al-Bukhari 7280', day: 'On Entering Paradise' },
  { arabic: 'آمِينَ يَقُولُهَا رَبُّنَا وَيَقُولُهَا الْمَلَائِكَةُ وَيَقُولُهَا الإِمَامُ', text: '"When the imam says Ameen, Allah and the angels say it too — so synchronize your Ameen with the imam\'s."', source: 'Sahih Al-Bukhari 782', day: 'On Ameen in Prayer' },
  { arabic: 'مَا مِنَ الأَيَّامِ يَوْمٌ أَفْضَلُ مِنْ يَوْمِ الْجُمُعَةِ', text: '"There is no day better than Friday — on it Adam was created, on it he entered Paradise, on it he was expelled, and the Hour will come on a Friday."', source: 'Sahih Muslim 854', day: 'On Friday' },
  { arabic: 'لَا تَخُصُّوا لَيْلَةَ الْجُمُعَةِ بِقِيَامٍ وَلَا يَوْمَهَا بِصِيَامٍ', text: '"Do not single out Friday night for extra prayer or Friday for fasting."', source: 'Sahih Muslim 1144', day: 'On Friday Fast' },
  { arabic: 'إِنَّ اللَّهَ يَغَارُ وَغَيْرَةُ اللَّهِ أَنْ يَأْتِيَ الْمُؤْمِنُ مَا حَرَّمَ اللَّهُ', text: '"Indeed Allah is jealous, and His jealousy is provoked when the believer does what Allah has forbidden."', source: 'Sahih Al-Bukhari 5223', day: 'On Avoiding Haram' },
  { arabic: 'مَنْ بَاتَ وَفِي يَدِهِ غَمَرٌ وَلَمْ يَغْسِلْهُ', text: '"Whoever sleeps with grease (food residue) on his hands without washing them — let him not blame anyone but himself."', source: 'Abu Dawud 3852 — Hasan', day: 'On Cleanliness' },
  { arabic: 'الدُّنْيَا لَعِنَةٌ مَلْعُونٌ مَا فِيهَا إِلَّا ذِكْرُ اللهِ', text: '"The world is cursed, and everything in it is cursed — except the remembrance of Allah and what helps in that."', source: 'Tirmidhi 2322 — Hasan', day: 'On Dunya and Dhikr' },
  { arabic: 'وَالْعَالِمُ وَالْمُتَعَلِّمُ شَرِيكَانِ فِي الأَجْرِ', text: '"The teacher and the student are partners in the reward."', source: 'Ibn Majah — Hasan', day: 'On Teaching and Learning' },
  { arabic: 'إِنَّكَ لَنْ تَدَعَ شَيْئًا اتِّقَاءَ اللهِ إِلَّا أَعْطَاكَ اللَّهُ خَيْرًا مِنْهُ', text: '"You will not give up anything for the sake of Allah except that Allah will give you something better in return."', source: 'Ahmad 22565 — Sahih', day: 'On Leaving Things for Allah' },
  { arabic: 'الدُّعَاءُ سِلَاحُ الْمُؤْمِنِ', text: '"Supplication is the weapon of the believer."', source: 'Al-Hakim — Hasan by Al-Albani', day: 'On Dua as Weapon' },
  { arabic: 'لِكُلِّ دَاءٍ دَوَاءٌ فَإِذَا أُصِيبَ دَوَاءُ الدَّاءِ بَرَأَ بِإِذْنِ اللهِ', text: '"For every illness there is a cure — when the right cure meets the illness, recovery comes by the permission of Allah."', source: 'Sahih Muslim 2204', day: 'On Seeking Treatment' },
  { arabic: 'مَا أَنْزَلَ اللَّهُ دَاءً إِلَّا أَنْزَلَ لَهُ شِفَاءً', text: '"Allah has not sent down any disease without sending down a cure for it."', source: 'Sahih Al-Bukhari 5678', day: 'On Shifa from Allah' },
  { arabic: 'الإِيمَانُ أَنْ تُؤْمِنَ بِاللهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الآخِرِ وَتُؤْمِنَ بِالْقَدَرِ', text: '"Faith is that you believe in Allah, His angels, His books, His messengers, the Last Day, and you believe in divine decree — its good and its bad."', source: 'Sahih Muslim 8', day: 'On Pillars of Faith' },
  { arabic: 'الإِسْلَامُ أَنْ تَشْهَدَ أَنْ لَا إِلَهَ إِلَّا اللهُ', text: '"Islam is that you testify there is no god but Allah and that Muhammad is His messenger, establish prayer, give zakat, fast Ramadan, and perform Hajj if able."', source: 'Sahih Muslim 8', day: 'On Pillars of Islam' },
  { arabic: 'الإِحْسَانُ أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ', text: '"Ihsan is that you worship Allah as if you see Him — and if you do not see Him, He sees you."', source: 'Sahih Muslim 8', day: 'On Ihsan' },
];
